import { api, track } from 'lwc';
import getWorkItemDetails from '@salesforce/apex/TimeLogController.getWorkItemDetails';
import getResourceAssignments from '@salesforce/apex/TimeLogController.getResourceAssignments';
import createTimeEntry from '@salesforce/apex/TimeLogController.createTimeEntry';
import Id from '@salesforce/user/Id';
import BaseComponent from 'c/baseComponent';

export default class TimeLogModal extends BaseComponent {
    @api workItemId;
    @track isOpen = false;
    @track isLoading = false;
    @track workItemName = '';
    @track projectId = '';
    @track resourceAssignments = [];
    @track selectedResourceAssignmentId = '';
    @track hours = '';
    @track description = '';
    @track date = this.getTodaysDate();

    currentUserId = Id;

    getTodaysDate() {
        const today = new Date();
        const year = today.getFullYear();
        const month = String(today.getMonth() + 1).padStart(2, '0');
        const day = String(today.getDate()).padStart(2, '0');
        return `${year}-${month}-${day}`;
    }

    @api
    openModal() {
        this.isOpen = true;
        this.loadWorkItemData();
    }

    closeModal() {
        this.isOpen = false;
        this.resetForm();
    }

    loadWorkItemData() {
        this.isLoading = true;

        getWorkItemDetails({ workItemId: this.workItemId })
            .then((result) => {
                this.workItemName = result.workItemName;
                this.projectId = result.projectId;
                return getResourceAssignments({
                    projectId: this.projectId,
                    currentUserId: this.currentUserId
                });
            })
            .then((assignments) => {
                this.resourceAssignments = assignments.map((ra) => ({
                    label: ra.resourceName,
                    value: ra.id,
                    isCurrentUser: ra.isCurrentUser
                }));

                // Default to current user's resource assignment if available
                const currentUserAssignment = this.resourceAssignments.find((ra) => ra.isCurrentUser);
                if (currentUserAssignment) {
                    this.selectedResourceAssignmentId = currentUserAssignment.value;
                } else if (this.resourceAssignments.length > 0) {
                    this.selectedResourceAssignmentId = this.resourceAssignments[0].value;
                }

                this.isLoading = false;
            })
            .catch((error) => {
                this.isLoading = false;
                this.showError('Failed to load work item details: ' + this.getErrorMessage(error));
            });
    }

    handleResourceChange(event) {
        this.selectedResourceAssignmentId = event.detail.value;
    }

    handleHoursChange(event) {
        this.hours = event.detail.value;
    }

    handleDescriptionChange(event) {
        this.description = event.detail.value;
    }

    handleDateChange(event) {
        this.date = event.detail.value;
    }

    handleSave() {
        if (!this.validateForm()) {
            return;
        }

        this.isLoading = true;

        const timeEntryData = {
            workItemId: this.workItemId,
            projectId: this.projectId,
            resourceAssignmentId: this.selectedResourceAssignmentId,
            hours: parseFloat(this.hours),
            description: this.description,
            entryDate: this.date
        };

        createTimeEntry({ timeEntryData: JSON.stringify(timeEntryData) })
            .then(() => {
                this.showSuccess('Time entry logged successfully');
                this.closeModal();
                this.dispatchRefreshEvent();
            })
            .catch((error) => {
                this.isLoading = false;
                this.showError('Failed to create time entry: ' + this.getErrorMessage(error));
            });
    }

    validateForm() {
        let isValid = true;

        if (!this.selectedResourceAssignmentId) {
            this.showError('Please select a resource');
            isValid = false;
        }

        if (!this.hours || parseFloat(this.hours) <= 0) {
            this.showError('Please enter valid hours (greater than 0)');
            isValid = false;
        }

        if (!this.description || this.description.trim() === '') {
            this.showError('Please enter a description');
            isValid = false;
        }

        if (!this.date) {
            this.showError('Please select a date');
            isValid = false;
        }

        return isValid;
    }

    resetForm() {
        this.workItemName = '';
        this.projectId = '';
        this.resourceAssignments = [];
        this.selectedResourceAssignmentId = '';
        this.hours = '';
        this.description = '';
        this.date = this.getTodaysDate();
    }

    dispatchRefreshEvent() {
        // Dispatch event to parent to refresh work item data
        this.dispatchEvent(
            new CustomEvent('timelogged', {
                detail: { workItemId: this.workItemId },
                bubbles: true,
                composed: true
            })
        );
    }

    getErrorMessage(error) {
        if (error.body && error.body.message) {
            return error.body.message;
        } else if (error.message) {
            return error.message;
        }
        return 'Unknown error occurred';
    }

    get hasResourceAssignments() {
        return this.resourceAssignments && this.resourceAssignments.length > 0;
    }

    get modalClass() {
        return this.isOpen ? 'slds-modal slds-fade-in-open' : 'slds-modal';
    }

    get backdropClass() {
        return this.isOpen ? 'slds-backdrop slds-backdrop_open' : 'slds-backdrop';
    }
}

