import { api, track } from 'lwc';
import getWorkItemTemplates from '@salesforce/apex/WorkItemCreateController.getWorkItemTemplates';
import getProjectResources from '@salesforce/apex/WorkItemCreateController.getProjectResources';
import createWorkItem from '@salesforce/apex/WorkItemCreateController.createWorkItem';
import BaseComponent from 'c/baseComponent';

export default class WorkItemCreateModal extends BaseComponent {
    @api projectId;
    @track isOpen = false;
    @track isSaving = false;
    @track parentWorkItemId = null;
    @track parentWorkItemName = '';

    // Form fields
    @track templateId = '';
    @track workItemName = '';
    @track summary = '';
    @track nextSteps = '';
    @track startDate = null;
    @track dueDate = null;
    @track estimatedHours = null;
    @track ownerId = '';

    // Picklist options
    @track templateOptions = [];
    @track resourceOptions = [];
    @track isLoadingData = false;
    @track isTemplateDisabled = false;
    @track isOwnerDisabled = false;

    /**
     * Open modal for creating a new work item
     * @param {Object} options - { parentWorkItemId, parentWorkItemName }
     */
    @api
    async open(options = {}) {
        this.isOpen = true;
        this.parentWorkItemId = options.parentWorkItemId || null;
        this.parentWorkItemName = options.parentWorkItemName || '';

        // Reset form
        this.resetForm();

        // Load picklist data
        await this.loadPicklistData();
    }

    /**
     * Load templates and resources
     */
    async loadPicklistData() {
        if (!this.projectId) {
            console.error('Cannot load picklist data: projectId is not set');
            return;
        }

        this.isLoadingData = true;

        try {
            // Load templates and resources in parallel
            const [templates, resources] = await Promise.all([
                getWorkItemTemplates({
                    projectId: this.projectId,
                    parentWorkItemId: this.parentWorkItemId
                }),
                getProjectResources({ projectId: this.projectId })
            ]);

            // Map templates to picklist options
            this.templateOptions = templates.map((option) => ({
                label: option.label,
                value: option.value
            }));

            // Auto-select and disable if only one template
            if (this.templateOptions.length === 1) {
                this.templateId = this.templateOptions[0].value;
                this.isTemplateDisabled = true;
            } else {
                this.isTemplateDisabled = false;
            }

            // Map resources to picklist options
            this.resourceOptions = resources.map((option) => ({
                label: option.label,
                value: option.value
            }));

            // Auto-select and disable if only one resource
            if (this.resourceOptions.length === 1) {
                this.ownerId = this.resourceOptions[0].value;
                this.isOwnerDisabled = true;
            } else {
                this.isOwnerDisabled = false;
            }
        } catch (error) {
            console.error('Error loading picklist data:', error);
            this.showError('Error loading form data: ' + (error.body?.message || error.message));
        } finally {
            this.isLoadingData = false;
        }
    }

    /**
     * Close modal
     */
    handleClose() {
        //console.log('Closing work item create modal');
        this.isOpen = false;
        this.resetForm();
    }

    /**
     * Reset form fields
     */
    resetForm() {
        //console.log('Resetting work item create form');
        this.templateId = '';
        this.workItemName = '';
        this.summary = '';
        this.nextSteps = '';
        this.startDate = null;
        this.dueDate = null;
        this.estimatedHours = null;
        this.ownerId = '';
    }

    /**
     * Handle field changes
     */
    handleTemplateChange(event) {
        this.templateId = event.detail.value;
    }

    handleNameChange(event) {
        this.workItemName = event.detail.value;
    }

    handleSummaryChange(event) {
        this.summary = event.detail.value;
    }

    handleNextStepsChange(event) {
        this.nextSteps = event.detail.value;
    }

    handleStartDateChange(event) {
        this.startDate = event.detail.value;
    }

    handleDueDateChange(event) {
        this.dueDate = event.detail.value;
    }

    handleEstimatedHoursChange(event) {
        this.estimatedHours = event.detail.value;
    }

    handleOwnerChange(event) {
        this.ownerId = event.detail.value;
    }

    /**
     * Handle save
     */
    async handleSave() {
        // Validate required fields
        if (!this.workItemName || this.workItemName.trim().length === 0) {
            this.showError('Work Item Name is required');
            return;
        }

        this.isSaving = true;

        try {
            const request = {
                projectId: this.projectId,
                parentWorkItemId: this.parentWorkItemId,
                templateId: this.templateId,
                name: this.workItemName.trim(),
                summary: this.summary,
                nextSteps: this.nextSteps,
                startDate: this.startDate,
                dueDate: this.dueDate,
                estimatedHours: this.estimatedHours,
                ownerId: this.ownerId
            };

            console.log('Creating work item with request:', JSON.stringify(request));
            const workItemId = await createWorkItem({ request });

            // Close modal first to avoid event issues
            this.handleClose();
            //console.log('Work item create modal closed after creation');
            // Show success message
            this.showSuccess('Work Item created successfully');

            // Dispatch event to parent (after modal is closed)
            this.dispatchEvent(
                new CustomEvent('workitemcreated', {
                    detail: {
                        workItemId,
                        parentWorkItemId: this.parentWorkItemId
                    },
                    bubbles: true,
                    composed: true
                })
            );
        } catch (error) {
            console.error('Error creating work item:', error);
            const errorMessage = error.body?.message || error.message || 'Unknown error creating work item';
            console.error('Full error details:', JSON.stringify(error));
            this.showError(errorMessage, 'Error Creating Work Item');
        } finally {
            this.isSaving = false;
            //console.log('Work item creation process completed');
        }
    }

    // Computed properties

    get modalTitle() {
        return this.parentWorkItemId ? `Add Child Work Item to ${this.parentWorkItemName}` : 'Create New Work Item';
    }

    get saveButtonLabel() {
        return this.isSaving ? 'Creating...' : 'Create';
    }
}

