import { api, wire, track } from 'lwc';
import { refreshApex } from '@salesforce/apex';
import getResourceAssignments from '@salesforce/apex/ProjectResourceController.getResourceAssignments';
import getProjectRoles from '@salesforce/apex/ProjectResourceController.getProjectRoles';
import saveResourceAssignment from '@salesforce/apex/ProjectResourceController.saveResourceAssignment';
import deleteResourceAssignment from '@salesforce/apex/ProjectResourceController.deleteResourceAssignment';
import recalculateProjectSharing from '@salesforce/apex/ProjectResourceController.recalculateProjectSharing';
import { getPicklistValues } from 'lightning/uiObjectInfoApi';
import RESOURCE_CLASSIFICATION_FIELD from '@salesforce/schema/Resource_Assignment__c.Resource_Classification__c';
import ACCESS_LEVEL_FIELD from '@salesforce/schema/Resource_Assignment__c.Access_Level__c';
import BaseComponent from 'c/baseComponent';

export default class ProjectResourceManager extends BaseComponent {
    @api recordId; // Project Id
    @track resourceAssignments = [];
    @track editingAssignment = null;
    @track isAddMode = false;
    @track isLoading = false;
    @track isExpanded = false; // Controls expanded/collapsed state - default to collapsed

    // Form fields for add/edit
    @track formData = {
        resourceClassification: '',
        defaultRoleId: '',
        accessLevel: '',
        resourceUserId: '',
        resourceContactId: '',
        notes: ''
    };

    @track projectRoles = [];
    wiredResourceAssignmentsResult;
    wiredProjectRolesResult;

    connectedCallback() {
        this.isExpanded = this.getLocalState(this.recordId, 'ProjectResourceManager.isExpanded', this.isExpanded);
    }

    // Wire resource classification picklist
    @wire(getPicklistValues, {
        recordTypeId: '012000000000000AAA',
        fieldApiName: RESOURCE_CLASSIFICATION_FIELD
    })
    resourceClassificationPicklist;

    // Wire access level picklist
    @wire(getPicklistValues, {
        recordTypeId: '012000000000000AAA',
        fieldApiName: ACCESS_LEVEL_FIELD
    })
    accessLevelPicklist;

    // Wire project roles
    @wire(getProjectRoles, { projectId: '$recordId' })
    wiredProjectRoles(result) {
        this.wiredProjectRolesResult = result;
        if (result.data) {
            this.projectRoles = result.data;
        } else if (result.error) {
            console.error('Error loading project roles:', result.error);
        }
    }

    // Wire resource assignments
    @wire(getResourceAssignments, { projectId: '$recordId' })
    wiredResourceAssignments(result) {
        this.wiredResourceAssignmentsResult = result;
        if (result.data) {
            this.resourceAssignments = result.data.map((assignment) => {
                const resourceName = assignment.cgpm__Resource_User__c ? assignment.cgpm__Resource_User__r?.Name : assignment.cgpm__Resource_Contact__r?.Name;
                const formattedStartDate = assignment.cgpm__Start_Date__c ? this.formatDate(assignment.cgpm__Start_Date__c) : '';
                const formattedEndDate = assignment.cgpm__End_Date__c ? this.formatDate(assignment.cgpm__End_Date__c) : '';

                return {
                    ...assignment,
                    resourceName,
                    formattedStartDate,
                    formattedEndDate,
                    initials: this.getInitials(resourceName),
                    tooltipText: this.getTooltipText({
                        ...assignment,
                        resourceName,
                        formattedStartDate,
                        formattedEndDate
                    })
                };
            });
            this.isLoading = false;
        } else if (result.error) {
            this.showError('Error loading resource assignments: ' + result.error.body.message);
            this.isLoading = false;
        }
    }

    get hasAssignments() {
        return this.resourceAssignments && this.resourceAssignments.length > 0;
    }

    get isFormOpen() {
        return this.isAddMode || this.editingAssignment !== null;
    }

    get formTitle() {
        return this.isAddMode ? 'Add Resource Assignment' : 'Edit Resource Assignment';
    }

    get saveButtonLabel() {
        return this.isAddMode ? 'Add' : 'Save';
    }

    get resourceClassificationOptions() {
        if (!this.resourceClassificationPicklist?.data) {
            return [];
        }
        return this.resourceClassificationPicklist.data.values;
    }

    get accessLevelOptions() {
        if (!this.accessLevelPicklist?.data) {
            return [];
        }
        return this.accessLevelPicklist.data.values;
    }

    get projectRoleOptions() {
        if (!this.projectRoles || this.projectRoles.length === 0) {
            return [];
        }
        return this.projectRoles.map((role) => ({
            label: role.Name,
            value: role.Id
        }));
    }

    get toggleIconName() {
        return this.isExpanded ? 'utility:chevrondown' : 'utility:chevronright';
    }

    get toggleTitle() {
        return this.isExpanded ? 'Collapse' : 'Expand';
    }

    get showUserLookup() {
        return this.formData.resourceClassification === 'Internal User' || this.formData.resourceClassification === 'External User';
    }

    get showContactLookup() {
        return this.formData.resourceClassification && this.formData.resourceClassification !== 'Internal User' && this.formData.resourceClassification !== 'External User';
    }

    handleToggle() {
        this.isExpanded = !this.isExpanded;
        this.setLocalState(this.recordId, 'ProjectResourceManager.isExpanded', this.isExpanded);
    }

    getInitials(name) {
        if (!name) {
            return '?';
        }
        const parts = name.trim().split(' ');
        if (parts.length === 1) {
            return parts[0].substring(0, 2).toUpperCase();
        }
        return (parts[0].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase();
    }

    getTooltipText(assignment) {
        let tooltip = assignment.resourceName || 'Unknown';

        // Add Default Role
        if (assignment.cgpm__Default_Role__r?.Name) {
            tooltip += '\nRole: ' + assignment.cgpm__Default_Role__r.Name;
        }

        // Add Default Access
        if (assignment.cgpm__Access_Level__c) {
            tooltip += '\nDefault Access: ' + assignment.cgpm__Access_Level__c;
        }

        // Add Start Date
        if (assignment.cgpm__Start_Date__c) {
            tooltip += '\nStart: ' + assignment.formattedStartDate;
        }

        // Add End Date
        if (assignment.cgpm__End_Date__c) {
            tooltip += '\nEnd: ' + assignment.formattedEndDate;
        }

        return tooltip;
    }

    handleAddNew() {
        this.isAddMode = true;
        this.editingAssignment = null;
        this.resetForm();
    }

    handleSecurity(event) {
        this.showInfo('Visibility and security options are planned for Phase 2', 'Coming Soon');
    }

    handleEdit(event) {
        const assignmentId = event.currentTarget.dataset.id;
        const assignment = this.resourceAssignments.find((a) => a.Id === assignmentId);

        if (assignment) {
            this.isAddMode = false;
            this.editingAssignment = assignmentId;
            this.formData = {
                resourceClassification: assignment.cgpm__Resource_Classification__c || '',
                defaultRoleId: assignment.cgpm__Default_Role__c || '',
                accessLevel: assignment.cgpm__Access_Level__c || '',
                resourceUserId: assignment.cgpm__Resource_User__c || '',
                resourceContactId: assignment.cgpm__Resource_Contact__c || '',
                notes: assignment.cgpm__Notes__c || ''
            };
        }
    }

    async handleDelete(event) {
        const assignmentId = event.currentTarget.dataset.id;

        if (!confirm('Are you sure you want to delete this resource assignment?')) {
            return;
        }

        this.isLoading = true;

        try {
            await deleteResourceAssignment({ assignmentId });
            this.showSuccess('Resource assignment deleted successfully');
            await refreshApex(this.wiredResourceAssignmentsResult);
        } catch (error) {
            this.showError('Error deleting resource assignment: ' + error.body.message);
        } finally {
            this.isLoading = false;
        }
    }

    handleFieldChange(event) {
        const field = event.target.dataset.field;

        // Create a new object with all updates at once (better for reactivity)
        let updates = {
            [field]: event.target.value
        };

        // When Default Role changes, auto-populate Resource Classification and Access Level
        if (field === 'defaultRoleId') {
            const selectedRoleId = event.target.value;

            if (selectedRoleId) {
                const selectedRole = this.projectRoles.find((role) => role.Id === selectedRoleId);

                if (selectedRole && selectedRole.cgpm__Resource_Type_Template__c) {
                    // Auto-populate Resource Classification
                    if (selectedRole.cgpm__Resource_Type_Template__r?.cgpm__Resource_Classification__c) {
                        updates.resourceClassification = selectedRole.cgpm__Resource_Type_Template__r.cgpm__Resource_Classification__c;

                        // Clear opposite resource field based on new classification
                        const classification = selectedRole.cgpm__Resource_Type_Template__r.cgpm__Resource_Classification__c;
                        if (classification === 'Internal User' || classification === 'External User') {
                            updates.resourceContactId = '';
                        } else {
                            updates.resourceUserId = '';
                        }
                    }

                    // Auto-populate Access Level
                    if (selectedRole.cgpm__Resource_Type_Template__r?.cgpm__Default_Access_Level__c) {
                        updates.accessLevel = selectedRole.cgpm__Resource_Type_Template__r.cgpm__Default_Access_Level__c;
                    }
                }
            }
        }

        // When Resource Classification changes, clear the opposite resource field
        if (field === 'resourceClassification') {
            if (this.showUserLookup) {
                // Clear Contact if switching to User-based type
                updates.resourceContactId = '';
            } else if (this.showContactLookup) {
                // Clear User if switching to Contact-based type
                updates.resourceUserId = '';
            }
        }

        // Apply all updates at once for better reactivity
        this.formData = {
            ...this.formData,
            ...updates
        };
    }

    checkForDuplicate() {
        // Check if the selected User or Contact already exists in the project's resource assignments
        const resourceIdToCheck = this.formData.resourceUserId || this.formData.resourceContactId;
        const fieldToCheck = this.formData.resourceUserId ? 'cgpm__Resource_User__c' : 'cgpm__Resource_Contact__c';

        const duplicate = this.resourceAssignments.find((assignment) => {
            // Skip the current record if we're editing
            if (!this.isAddMode && assignment.Id === this.editingAssignment) {
                return false;
            }

            // Check if the User or Contact already exists
            return assignment[fieldToCheck] === resourceIdToCheck;
        });

        if (duplicate) {
            const resourceName = duplicate.resourceName || 'This resource';
            this.showError(`${resourceName} is already assigned to this project`);
            return true;
        }

        return false;
    }

    async handleSave() {
        // Validate required fields
        if (!this.formData.resourceClassification) {
            this.showError('Resource Classification is required');
            return;
        }

        if (!this.formData.accessLevel) {
            this.showError('Access Level is required');
            return;
        }

        // Validate User or Contact based on Resource Classification
        if (this.showUserLookup && !this.formData.resourceUserId) {
            this.showError('Please select a User');
            return;
        }

        if (this.showContactLookup && !this.formData.resourceContactId) {
            this.showError('Please select a Contact');
            return;
        }

        // Check for duplicate Resource User or Contact
        if (this.checkForDuplicate()) {
            return; // Error toast already shown in checkForDuplicate
        }

        this.isLoading = true;

        try {
            const assignmentData = {
                Id: this.isAddMode ? null : this.editingAssignment,
                cgpm__Project__c: this.recordId,
                cgpm__Resource_Classification__c: this.formData.resourceClassification,
                cgpm__Default_Role__c: this.formData.defaultRoleId || null,
                cgpm__Access_Level__c: this.formData.accessLevel,
                cgpm__Resource_User__c: this.formData.resourceUserId || null,
                cgpm__Resource_Contact__c: this.formData.resourceContactId || null,
                cgpm__Notes__c: this.formData.notes || null
            };

            await saveResourceAssignment({ assignment: assignmentData });

            this.showSuccess(this.isAddMode ? 'Resource assignment added successfully' : 'Resource assignment updated successfully');

            this.handleCancel();
            await refreshApex(this.wiredResourceAssignmentsResult);
        } catch (error) {
            this.showError('Error saving resource assignment: ' + error.body.message);
        } finally {
            this.isLoading = false;
        }
    }

    handleCancel() {
        this.isAddMode = false;
        this.editingAssignment = null;
        this.resetForm();
    }

    resetForm() {
        this.formData = {
            resourceClassification: '',
            defaultRoleId: '',
            accessLevel: '',
            resourceUserId: '',
            resourceContactId: '',
            notes: ''
        };
    }

    formatDate(dateString) {
        if (!dateString) {
            return '';
        }
        const date = new Date(dateString);
        return date.toLocaleDateString();
    }

    async handleRecalculateSharing() {
        if (!confirm('This will recalculate all sharing rules for this project and its work items. This may take a few moments. Continue?')) {
            return;
        }

        this.isLoading = true;

        try {
            await recalculateProjectSharing({ projectId: this.recordId });
            this.showSuccess('Sharing rules recalculated successfully');
        } catch (error) {
            this.showError('Error recalculating sharing: ' + (error.body?.message || error.message));
        } finally {
            this.isLoading = false;
        }
    }
}

